@push('scripts')
<script>
(()=>{const form=document.getElementById('placement-batch-form');if(!form)return;
const search=document.getElementById('placement-search'),groups=[...form.querySelectorAll('.placement-major')],boxes=[...form.querySelectorAll('.placement-student-check:not(:disabled)')];
function refresh(){const selected=boxes.filter(b=>b.checked),hidden=selected.filter(b=>b.closest('tr').hidden).length;document.getElementById('placement-count').textContent=selected.length+' siswa dipilih'+(hidden?' ('+hidden+' tersembunyi oleh pencarian)':'');document.getElementById('placement-submit').disabled=!selected.length;const list=document.getElementById('placement-selected-list');list.replaceChildren();selected.forEach(b=>{const li=document.createElement('li');li.textContent=b.dataset.name;list.append(li)});groups.forEach(g=>{const available=[...g.querySelectorAll('.placement-student-check:not(:disabled)')],n=available.filter(b=>b.checked).length,parent=g.querySelector('.placement-major-check');parent.checked=available.length>0&&n===available.length;parent.indeterminate=n>0&&n<available.length;parent.disabled=!available.length;});}
groups.forEach(g=>{g.querySelector('.placement-major-check').addEventListener('change',e=>{g.querySelectorAll('.placement-student-check:not(:disabled)').forEach(b=>b.checked=e.target.checked);g.open=true;refresh();});});boxes.forEach(b=>b.addEventListener('change',refresh));
search.addEventListener('input',()=>{const q=search.value.trim().toLocaleLowerCase('id');groups.forEach(g=>{const rows=[...g.querySelectorAll('.placement-candidate')];rows.forEach(r=>r.hidden=!r.dataset.search.includes(q));g.hidden=rows.every(r=>r.hidden);if(q&&!g.hidden)g.open=true;});document.getElementById('placement-no-results').hidden=groups.some(g=>!g.hidden);refresh();});
document.getElementById('placement-select-visible').addEventListener('click',()=>{boxes.filter(b=>!b.closest('tr').hidden&&!b.closest('.placement-major').hidden).forEach(b=>{b.checked=true;b.closest('details').open=true;});refresh();});document.getElementById('placement-clear').addEventListener('click',()=>{boxes.forEach(b=>b.checked=false);refresh();});groups.filter(g=>g.querySelector('input[name="roster_ids[]"]:checked')).forEach(g=>g.open=true);refresh();})();
</script>
@endpush
